      "story": "生涯にわたる重度の喘息持ちでありながら太い葉巻を好んだ。モンテクリスト、パルタガス、H.アップマンなど当時の上等な銘柄を愛し、なかでもモンテクリストNo.4を好んだと伝えられる。本人は贅沢や特権・贈り物をほとんど受け取らなかったが、書物と葉巻だけは例外だったという。窮地にあってもカストロが最後の葉巻の供給元となり、1967年3月22日、ボリビアで戦うゲバラのもとにカストロからチャーチル（大型サイズ）が一箱届き、自分の分を吸って残りは部下に分け与えたと伝えられる。ベレー帽に葉巻という姿は、反帝国主義とキューバ革命の象徴的イメージとして世界に広まった。",
