      "story": "葉巻をラグジュアリー志向のライフスタイルの一部として体現し、2009年6月には『シガー・アフィシオナード』誌の表紙を飾った。2013年12月にはコイーバと組み、米国産のコネチカット・ハバナ葉を使った6×52トロの超高級葉巻『コマドール（Comador）』を発表した（同銘柄は比較的短期間で製造が終了）。個人的な好みについては『モンテクリストが一番だろうね。でもロメオ・イ・フリエタもパルタガスも、何でも吸う』と語り、太めでマイルドな一本を好むという。",
