      "field": "音楽（ジャズ）",
      "era": "1917–1993",
      "story": "ビバップを築いたトランペットの巨匠。ベレー帽、角縁眼鏡、上向きに曲がったトランペット、そして大きく膨らむ頬がトレードマークだった（頬の膨らみは長年の演奏で鍛えられた筋肉によるもので、葉巻とは別）。キューバ音楽をジャズに融合させた先駆者としてキューバとの縁も深く、1985年の再訪(『A Night in Havana』)ではカストロから葉巻を贈られ、その一本はキューバのテレビ番組でも披露された。ハバナ産葉巻を愛したことで知られるが、具体的な愛用銘柄については諸説あり確証は薄い。",
