      "era": "1822–1885",
      "story": "南北戦争の北軍総司令官にして第18代米国大統領。開戦当初は軽い喫煙者だったが、戦況が激化するにつれ本数が増え、荒野の戦いの頃には日の出から日没まで1日20本を吸うほどになったという。1862年のフォート・ドネルソン攻略の際、新聞が『戦闘のさなかに葉巻をくわえる将軍』として報じたことから、感謝した市民から上等な葉巻が続々と届き、一説には約10,000箱にのぼり、とても吸いきれない量になったと伝えられる。長年の喫煙は喉のがんにつながり、1884年に咽頭がんと診断される。同年11月20日に『これが最後の一本』と葉巻を断ち、死病と競うように回想録を書き上げ、脱稿の5日後、1885年7月23日に世を去った。晩年は投資の失敗で財産を失い、家族に遺すため病苦を押して筆を執り続けた。完成した『グラント将軍回顧録』はマーク・トウェインの出版社から刊行されて大成功を収め、遺族を救った。がんで没した唯一の米大統領である。戦場でも動じず葉巻をくゆらせる将軍像は、19世紀アメリカにおける『葉巻＝胆力と指導力』というイメージの原型の一つとなった。",
