      "story": "『ミスター・テレビジョン』と呼ばれた米国初期テレビの顔。子役だった13歳頃（1921年頃）に初めてハバナ葉巻を口にし、93歳で亡くなるまで吸い続けた生涯の愛好家である。NBCと契約して大成してからはH.アップマン、ロメオ・イ・フリエタ、コイーバといったキューバ銘柄を好んだ。巨大な葉巻を愛したことで知られ、二番目の妻ルースが新婚旅行のパリで、彼の特大のハバナを4本収められる大きさのイブニングバッグを探し当てたという逸話や、パリから発つ際に約500本のハバナを詰め込もうとして『持ち込みは100本まで』と税関に止められた話、シュワルツェネッガー宅で勧められるまま何本もヒュミドールから稀少な一本を失敬した話など、葉巻をめぐる愉快な逸話に事欠かなかった。ボブ・ホープやジョージ・バーンズら同時代の喜劇人と並ぶ『葉巻をくわえたコメディアン』の典型であり、その巨大な一本は豪放なステージ人格そのものの延長でもあった。",
      "favorite": "H.アップマン、ロメオ・イ・フリエタ、コイーバ"
